// SoftHSMv3 WASM: Generate Ephemeral Key // Profile A uses X25519; Profile B uses P-256 const { pubHandle: ephPub, privHandle: ephPriv } = hsm_generateECKeyPair( hsmd, sessionHandle, 'X25519' /* or 'P-256' for Profile B */ );
